  reg [63:0] win_lfsr = 64'h1D2CACE15EED0001;
  reg [6:0] u = 0;
  reg [7167:0] rec = 0;
  localparam REC = 0, SEND = 1;
  reg state = REC;

  function [7:0] hex(input [3:0] v);
    hex = v < 10 ? 8'h30 + v : 8'h37 + v;
  endfunction

  reg [10:0] ci = 0;
  reg [7:0] ch;
  always @* begin
    if (ci == 0) ch = "R";
    else if (ci < 17) ch = hex(win_lfsr[63 - 4 * (ci - 1) -: 4]);
    else if (ci < 1809) ch = hex(rec[7167 - 4 * (ci - 17) -: 4]);
    else if (ci == 1809) ch = 8'h0d;
    else ch = 8'h0a;
  end

  reg tx = 1, busy = 0;
  reg [7:0] baud = 0;
  reg [3:0] bitn = 0;
  reg [9:0] shift = 10'h3ff;

  always @(posedge clk_25mhz) begin
    lfsr <= step_lfsr(lfsr);
    case (state)
      REC: begin
        if (u == 0) win_lfsr <= lfsr;
        rec <= {rec[7111:0], s};
        u <= u + 1;
        if (u == 127) begin
          state <= SEND;
          u <= 0;
        end
      end
      SEND:
        if (!busy) begin
          shift <= {1'b1, ch, 1'b0};
          busy <= 1;
          baud <= 0;
          bitn <= 0;
        end else if (baud == 216) begin
          baud <= 0;
          tx <= shift[0];
          shift <= {1'b1, shift[9:1]};
          bitn <= bitn + 1;
          if (bitn == 9) begin
            busy <= 0;
            if (ci == 1810) begin
              ci <= 0;
              state <= SEND;
            end else ci <= ci + 1;
          end
        end else baud <= baud + 1;
    endcase
  end

  assign ftdi_rxd = tx;
